import React from 'react';
import { useNavigate } from 'react-router-dom';
import Footer from '../../UI/Footer/Footer';
import img1 from '../../../assets/charity_walk.png'
import img2 from '../../../assets/.png'
import img3 from '../../../assets/charity_walk.png'


const events = [
  {
    title: 'Sports day',
    description:
      'Celebrate Sports Day on June 15 in Seychelles with exciting games, teamwork, and community',
    date: 'June 15, 2025',
    status: 'upcoming',
    image: 'assets/sports.png',
    link: 'upcoming_event.html',
  },
  {
    title: 'Navratri',
    description:
      'Celebrate Navratri with vibrant dances, devotion, and cultural unity honoring the divine feminine.',
    date: 'June 25, 2025',
    status: 'completed',
    image: 'assets/deafult.png',
  },
  {
    title: 'Event heading',
    description: 'event description. Maximum 2 lines.',
    date: 'June 25, 2025',
    status: 'ongoing',
    image: 'assets/deafult.png',
  },
];
// import Footer from '../../UI/Footer/Footer';
// import Footer from '../../UI/Footer/Footer';
const statusClasses = {
  upcoming: 'bg-blue-100 text-blue-500',
  completed: 'bg-orange-100 text-orange-500',
  ongoing: 'bg-yellow-100 text-yellow-600',
};

const EventsPage = () => {
  const navigate = useNavigate();

  return (
    <>
    <div className="bg-white text-gray-800 font-sans min-h-screen">
      {/* Back Button */}
      <div className="p-6">
        <button
          className="border rounded-full px-4 py-1 text-sm hover:bg-gray-100"
          onClick={() => navigate(-1)}
        >
          ⬅ Back To Home
        </button>
      </div>

      {/* Header */}
      <section className="text-center px-4">
        <h2 className="text-4xl font-bold mb-2">Our Events</h2>
        <p className="text-gray-600 max-w-xl mx-auto mb-6">
          Stay connected with our vibrant community. Discover celebrations,
          gatherings, and learning opportunities.
        </p>

        {/* Category Filters */}
        <div className="flex justify-center gap-6 mb-10">
          {['All', 'Upcoming', 'Past'].map((label, index) => (
            <button
              key={index}
              className={`px-4 py-2 rounded-full text-sm ${
                index === 0
                  ? 'bg-orange-500 text-white'
                  : 'text-gray-700 hover:bg-gray-100'
              }`}
            >
              {label}
            </button>
          ))}
        </div>

        {/* Events Grid */}
        <div className="max-w-6xl mx-auto grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-6">
          {events.map((event, idx) => {
            const StatusTag = (
              <span
                className={`px-2 py-0.5 rounded text-xs ${
                  statusClasses[event.status] || ''
                }`}
              >
                {event.status.charAt(0).toUpperCase() + event.status.slice(1)}
              </span>
            );

            const CardContent = (
              <div className="bg-white rounded shadow p-4 text-left hover:shadow-lg transition duration-200">
                <img
                  src={event.image}
                  alt="Event"
                  className="rounded mb-4 w-full h-40 object-cover"
                />
                <h3 className="font-bold text-sm mb-1">{event.title}</h3>
                <p className="text-sm text-gray-600">{event.description}</p>
                <div className="flex justify-between items-center text-xs mt-3">
                  <span className="flex items-center gap-1">📅 {event.date}</span>
                  {StatusTag}
                </div>
              </div>
            );

            return event.link ? (
              <a href={event.link} key={idx}>
                {CardContent}
              </a>
            ) : (
              <div key={idx}>{CardContent}</div>
            );
          })}
        </div>

        {/* Pagination */}
        <div className="mt-10 flex justify-center gap-2">
          {[1, 2, 3, 4].map((page) => (
            <button key={page} className="px-3 py-1 border rounded">
              {page}
            </button>
          ))}
          <span className="px-3 py-1">...</span>
        </div>
      </section>
    </div>
    <Footer/>
    </>
  );
};

export default EventsPage;
